def check_character_frequency(S: str) -> str:
    frequency_count = {}
    for s in S:
        if s in frequency_count:
            frequency_count[s] += 1
        else:
            frequency_count[s] = 1

    count_of_frequencies = {}
    for frequency in frequency_count.values():
        if frequency in count_of_frequencies:
            count_of_frequencies[frequency] += 1
        else:
            count_of_frequencies[frequency] = 1

    ans = "Yes"
    for f in count_of_frequencies:
        if count_of_frequencies[f] != 0 and count_of_frequencies[f] != 2:
            ans = "No"
            break

    return ans
